// Generated by Cypress Author on 2026-10-11.
import Box from '@mui/material/Box';
import type { NowPlayingTrack, PlayedTrack } from '../api.ts';
import {
  collaborationTrack,
  nowPlayingTrack,
  pausedTrack,
  playedTrack,
  trackWithoutCover,
  trackWithWideCover,
} from '../../cypress/fixtures/recentlyPlayed.ts';
import { stubAlbumCover, waitForAlbumCovers } from '../../cypress/support/albumCover.ts';
import TrackItem from './TrackItem.tsx';

const item = '[data-cy="track-item"]';

/** Mounts the track on a white card background with the card's padding, as the listening history shows it. */
function mountTrack(play: PlayedTrack | NowPlayingTrack) {
  cy.mount(
    <Box sx={{ px: 3, backgroundColor: 'background.paper' }}>
      <TrackItem play={play} />
    </Box>,
  );
}

describe('<TrackItem />', () => {
  beforeEach(() => {
    stubAlbumCover();
  });

  it('shows the album cover, song, performer, time of listening and duration', () => {
    mountTrack(playedTrack);

    cy.get(item).within(() => {
      cy.get('img')
        .should('have.attr', 'src', '/fixtures/album-cover.png')
        .and('have.attr', 'alt', 'Harbour Lights album cover');
      cy.get('[data-cy="track-name"]').should('have.text', 'Paper Lanterns');
      cy.get('[data-cy="track-artists"]').should('have.text', 'The Velvet Tides');
      // Intl may separate "PM" with a narrow no-break space, which `\s` matches.
      cy.get('[data-cy="track-played-at"]')
        .should('have.attr', 'datetime', playedTrack.playedAt)
        .invoke('text')
        .should('match', /^2:05\sPM$/);
      cy.get('[data-cy="track-duration"]').should('have.text', '3:45');
      // A play from the history has ended: it has no playback marker.
      cy.get('[data-cy="track-playback"]').should('not.exist');
    });
  });

  // Generated by Cypress Author on 2026-10-11.
  it('the track playing now → marked "Now playing", with when it started and its duration', () => {
    mountTrack(nowPlayingTrack);

    cy.get(item).within(() => {
      cy.get('[data-cy="track-name"]').should('have.text', 'Golden Hour Drive');
      cy.get('[data-cy="track-artists"]').should('have.text', 'Sunset Avenue');
      cy.get('[data-cy="track-playback"]').should('be.visible').and('have.text', 'Now playing');
      cy.get('[data-cy="track-played-at"]')
        .should('have.attr', 'datetime', nowPlayingTrack.playedAt)
        .invoke('text')
        .should('match', /^5:58\sPM$/);
      cy.get('[data-cy="track-duration"]').should('have.text', '4:01');
    });
  });

  // Generated by Cypress Author on 2026-10-11.
  it('the track playing now is paused → marked "Paused"', () => {
    mountTrack(pausedTrack);

    cy.get(`${item} [data-cy="track-playback"]`).should('be.visible').and('have.text', 'Paused');
  });

  it('several performers and a track over an hour → lists every performer and shows hours', () => {
    mountTrack(collaborationTrack);

    cy.get('[data-cy="track-artists"]').should('have.text', 'Aurora Fields, Nils Berg, The Copenhagen Strings');
    cy.get('[data-cy="track-duration"]').should('have.text', '1:02:03');
  });

  it('cover that is not square → shown whole in a 72px square frame, not cropped', () => {
    mountTrack(trackWithWideCover);

    waitForAlbumCovers(item);
    cy.get(`${item} img`).should('have.css', 'object-fit', 'contain');
    cy.get(`${item} .MuiAvatar-root`).should('have.css', 'width', '72px').and('have.css', 'height', '72px');
  });

  it('album without a cover → shows a music note instead', () => {
    mountTrack(trackWithoutCover);

    cy.get(item).within(() => {
      cy.get('img').should('not.exist');
      cy.get('[data-testid="MusicNoteRoundedIcon"]').should('be.visible');
    });
  });

  it('matches the visual baseline', () => {
    cy.viewport(600, 120);
    mountTrack(playedTrack);

    cy.contains('Paper Lanterns').should('be.visible');
    waitForAlbumCovers(item);
    cy.get(item).matchImage();
  });

  // On a phone, a long title and performer list are cut short with an ellipsis.
  it('matches the visual baseline with several artists and a long title on a phone', () => {
    cy.viewport(360, 120);
    mountTrack(collaborationTrack);

    cy.contains('Midnight Train').should('be.visible');
    waitForAlbumCovers(item);
    cy.get(item).matchImage();
  });

  it('matches the visual baseline with a wide album cover', () => {
    cy.viewport(600, 120);
    mountTrack(trackWithWideCover);

    cy.contains('Live at the Lighthouse').should('be.visible');
    waitForAlbumCovers(item);
    cy.get(item).matchImage();
  });

  it('matches the visual baseline without an album cover', () => {
    cy.viewport(600, 120);
    mountTrack(trackWithoutCover);

    cy.get('[data-testid="MusicNoteRoundedIcon"]').should('be.visible');
    cy.get(item).matchImage();
  });

  // Generated by Cypress Author on 2026-10-11.
  it('matches the visual baseline while playing now', () => {
    cy.viewport(600, 120);
    mountTrack(nowPlayingTrack);

    cy.contains('Now playing').should('be.visible');
    waitForAlbumCovers(item);
    cy.get(item).matchImage();
  });

  // Generated by Cypress Author on 2026-10-11.
  it('matches the visual baseline while paused', () => {
    cy.viewport(600, 120);
    mountTrack(pausedTrack);

    cy.contains('Paused').should('be.visible');
    waitForAlbumCovers(item);
    cy.get(item).matchImage();
  });

  // Generated by Cypress Author on 2026-10-11.
  // On a phone the marker must still fit next to the cover without squeezing the time and duration.
  it('matches the visual baseline while playing now on a phone', () => {
    cy.viewport(360, 120);
    mountTrack(nowPlayingTrack);

    cy.contains('Now playing').should('be.visible');
    waitForAlbumCovers(item);
    cy.get(item).matchImage();
  });
});
